import {translationControl,bindTranslations} from './translation.js?v=7';
import {createCaseLibrary} from './pb20.js?v=7';
// A shared quiz experience keeps bank progress and option identities separate.
export function createQuiz({getStore,save,toast,render,lessons,allQuestions,extra,pb,track=()=>{}}) {
 const $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const byId=Object.fromEntries(allQuestions.map(q=>[q.id,q])), letters='ABCDEF';
 const banks={ib400:{title:'IB400',headline:'Know why your answer is right.',intro:'400 original questions with five choices each. Build the foundations, combine the mechanisms, then test the edge cases.',levels:['Tutorial','Exam','Challenge']},st100:{title:'S&T100',headline:'Make the models work together.',intro:'100 synthesis questions with six choices each. Go beyond IB400 Challenge with simultaneous shocks, competing mechanisms, constraints and reverse reasoning.',levels:['S&T']},pb20:{title:'PB20',levels:['Exam','Challenge','S&T']},recaps:{title:'Assoc. Prof Wong Wei Kang Recaps',headline:'Rebuild every tutorial, one decision at a time.',intro:'All ten supplied tutorials converted into revision MCQs. Work through each requested part, explain the tempting mistakes, and connect the answer to Decoded.',levels:['Recap']}};
 const PB=createCaseLibrary({pb,getStore,start,byId});
 let filters={},timer;
 const bankOf=q=>q?.bank||'ib400', pool=b=>allQuestions.filter(q=>bankOf(q)===b), lesson=id=>lessons.find(l=>l.id===id);
 const sessionBank=s=>banks[s?.bank]?s.bank:bankOf(byId[s?.ids?.[0]]);
 const title=b=>banks[b]?.title||banks.ib400.title;
 const label=q=>bankOf(q)==='pb20'?`PB20 ${q.caseId.slice(2)} · Part ${q.part}`:bankOf(q)==='st100'?`S&T ${q.id-1000}`:bankOf(q)==='recaps'?`Tutorial ${q.tutorial} · ${q.part}`:`IB400 ${q.id}`;
 const shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
 const validChoice=(id,v)=>byId[id]&&Number.isInteger(v)&&v>=0&&v<byId[id].choices.length;
 function orders(s){s.orders??={};s.strikes??={};s.drafts??={};s.confidence??={};let changed=false;for(const id of s.ids){const a=s.orders[id],n=byId[id].choices.length;if(!Array.isArray(a)||a.length!==n||new Set(a).size!==n||a.some(i=>!validChoice(id,i))){s.orders[id]=shuffle(Array.from({length:n},(_,i)=>i));changed=true}}if(changed)save()}
 const letter=(s,id,i)=>letters[s.orders[id].indexOf(i)];
 function stats(bank){const qs=pool(bank),attempts=qs.filter(q=>getStore().answers[q.id]&&!getStore().answers[q.id].needsReview),right=attempts.filter(q=>getStore().answers[q.id].correct);return `<div class="stats-row"><div class="stat"><strong>${attempts.length}<small class="small"> / ${qs.length}</small></strong><span>QUESTIONS ATTEMPTED</span></div><div class="stat"><strong>${attempts.length?Math.round(right.length/attempts.length*100):0}%</strong><span>LATEST ANSWER ACCURACY</span></div><div class="stat"><strong>${qs.filter(q=>getStore().bookmarks.includes(q.id)).length}</strong><span>BOOKMARKED</span></div><div class="stat"><strong>${qs.filter(q=>getStore().answers[q.id]&&(!getStore().answers[q.id].correct||getStore().answers[q.id].needsReview)).length}</strong><span>QUESTIONS TO REVISIT</span></div></div>`}
 function filtered(){return pool(filters.bank).filter(q=>(filters.lesson==='all'||q.lesson===filters.lesson)&&(filters.tutorial==='all'||q.tutorial===Number(filters.tutorial))&&(filters.difficulty==='all'||q.difficulty===filters.difficulty)&&(!filters.concept||q.concept===filters.concept)&&(!filters.search||[q.prompt,...q.choices.map(c=>c.text),lesson(q.lesson)?.title,q.part].join(' ').toLowerCase().includes(filters.search.toLowerCase()))&&((s=>s==='all'||s==='new'&&(!getStore().answers[q.id]||getStore().answers[q.id].needsReview)||s==='wrong'&&getStore().answers[q.id]&&(!getStore().answers[q.id].correct||getStore().answers[q.id].needsReview)||s==='bookmarked'&&getStore().bookmarks.includes(q.id)||s==='uncertain'&&getStore().answers[q.id]&&getStore().answers[q.id].confidence!=='confident')(filters.status)))}
 function recapMap(){return `<section class="coverage-section"><h2>Every tutorial part, mapped</h2><p>Original MCQ adaptations checked against the supplied question papers and solution sketches. Open a question directly or practise a whole tutorial above.</p>${Array.from({length:10},(_,i)=>i+1).map(t=>{const rows=extra.coverage.filter(r=>r.tutorial===t),qs=pool('recaps').filter(q=>q.tutorial===t);return `<details class="source-card" ${Number(filters.tutorial)===t?'open':''}><summary><strong>Tutorial ${t}</strong><span class="small"> · ${rows.length} parts · ${qs.length} MCQs</span></summary><div class="recap-parts">${rows.map(r=>`<div><strong>${E(r.part)}</strong><span>${E(r.topic)}</span><div>${r.questionIds.map(id=>`<a class="inline-link" href="#question/${id}">Question ${qs.findIndex(q=>q.id===id)+1} ↗</a>`).join(' · ')}</div></div>`).join('')}</div></details>`}).join('')}</section>`}
 function lobby(bank='ib400',lid,cid){if(!banks[bank])bank='ib400';filters={bank,lesson:lesson(lid)?lid:'all',tutorial:bank==='recaps'&&Number(lid)>=1&&Number(lid)<=10?lid:'all',difficulty:'all',status:'all',search:'',concept:cid||''};if(bank==='pb20')return PB.lobby();const b=banks[bank],qs=pool(bank),s=getStore().session;return `<p class="eyebrow">${E(b.title)} · THE QUESTION BANK</p><h1>${E(b.headline)}</h1><p class="intro">${E(b.intro)}</p>${stats(bank)}<div class="filter-panel"><label>${bank==='recaps'?'Tutorial':'Chapter'}<select id="filter-${bank==='recaps'?'tutorial':'lesson'}"><option value="all">${bank==='recaps'?'All 10 tutorials':'All 12 chapters'}</option>${bank==='recaps'?Array.from({length:10},(_,i)=>i+1).map(t=>`<option value="${t}" ${Number(filters.tutorial)===t?'selected':''}>Tutorial ${t}</option>`).join(''):lessons.map(l=>`<option value="${l.id}" ${filters.lesson===l.id?'selected':''}>${E(l.title)}</option>`).join('')}</select></label><label>Difficulty<select id="filter-difficulty"><option value="all">All levels in this bank</option>${b.levels.map(d=>`<option>${E(d)}</option>`).join('')}</select></label><label>Review queue<select id="filter-status"><option value="all">All questions</option><option value="new">Unattempted</option><option value="wrong">Incorrect or revised</option><option value="bookmarked">Bookmarked</option><option value="uncertain">Unsure or guessed</option></select></label><label>Search<input id="filter-search" type="search" placeholder="Keyword, idea or equation…"></label></div>${cid?`<div class="note">Focused on ${E(lesson(lid)?.concepts.find(c=>c.id===cid)?.title||cid)}. <button class="inline-link" id="clear-concept">Show all chapter concepts</button></div>`:''}<div class="session-options"><span id="pool-count">${filtered().length} matching questions</span><select id="session-mode" aria-label="Practice or exam mode"><option value="practice">Practice · immediate explanations</option><option value="exam">Exam · explanations after finishing</option></select><select id="session-count" aria-label="Number of questions"><option value="10">10 questions</option><option value="20" selected>20 questions</option><option value="40">40 questions</option><option value="100">100 questions</option><option value="all">All matching questions</option></select><select id="session-order" aria-label="Question order"><option value="source" ${bank==='recaps'?'selected':''}>Source order</option><option value="shuffle" ${bank!=='recaps'?'selected':''}>Shuffle questions</option></select><select id="session-minutes" aria-label="Session timer"><option value="0">Untimed</option><option value="30">30 minutes</option><option value="60">60 minutes</option><option value="120">120 minutes</option></select><button class="primary" id="start-session" ${filtered().length?'':'disabled'}>Start a new set →</button></div>${s?`<div class="note"><strong>Saved ${E(title(sessionBank(s)))} ${s.mode} session</strong> · ${Object.keys(s.responses).length} / ${s.ids.length} answered. <a class="inline-link" href="#session">${s.finished?'Review results':'Continue session'} ↗</a></div>`:''}<div class="note">Cross out any option without selecting it. Redo a question or a full set with fresh option order. Your attempt count and first-answer result are retained. Starting a new set replaces the active session. Your account syncs progress and records study activity for the site owner. Export progress keeps a backup.</div>${bank==='recaps'?`<p class="small">These are independent study adaptations. The section name identifies the course lecturer; it does not imply endorsement.</p>${recapMap()}`:`<p class="small">${bank==='st100'?'Designed above IB400 Challenge through deeper combinations of course concepts.':'Tutorial builds foundations. Exam combines mechanisms. Challenge tests limits and competing explanations.'} Difficulty is a study-design judgment. These are original practice questions, not official exam questions.</p><div class="section-head"><h2>Your course coverage</h2><p>Each question links back to Decoded.</p></div><div class="table-wrap"><table class="coverage-table"><thead><tr><th>Chapter</th><th>Questions</th><th>Attempted</th><th>Latest correct</th><th></th></tr></thead><tbody>${lessons.map(l=>{const items=qs.filter(q=>q.lesson===l.id),a=items.filter(q=>getStore().answers[q.id]&&!getStore().answers[q.id].needsReview);return `<tr><td>${E(l.title)}</td><td>${items.length}</td><td>${a.length}</td><td>${a.filter(q=>getStore().answers[q.id].correct).length}</td><td><a class="inline-link" href="#${bank}/${l.id}">Practise ↗</a></td></tr>`}).join('')}</tbody></table></div>`}`}
 function start(ids,bank,mode='practice',minutes=0,replaceHash=false){getStore().session={bank,ids,mode,index:0,responses:{},drafts:{},strikes:{},confidence:{},orders:{},finished:false,started:Date.now(),end:minutes?Date.now()+minutes*60000:null};track('session_start',{bank,mode,minutes,questionIds:ids});save();if(location.hash==='#session')render();else if(replaceHash)location.replace('#session');else location.hash='session'}
 function bindLobby(){if(filters.bank==='pb20'){PB.bindLobby();return}for(const k of ['lesson','tutorial','difficulty','status','search'])$('#filter-'+k)?.addEventListener(k==='search'?'input':'change',e=>{filters[k]=e.target.value;if(k==='lesson')filters.concept='';$('#pool-count').textContent=filtered().length+' matching questions';$('#start-session').disabled=!filtered().length});$('#clear-concept')?.addEventListener('click',()=>{filters.concept='';$('#clear-concept').parentElement.remove();$('#pool-count').textContent=filtered().length+' matching questions'});$('#start-session').onclick=()=>{let ids=filtered().map(q=>q.id);if(!ids.length)return toast('No matching questions');if($('#session-order').value==='shuffle')shuffle(ids);const count=$('#session-count').value;start(count==='all'?ids:ids.slice(0,Number(count)),filters.bank,$('#session-mode').value,Number($('#session-minutes').value))}}
 function record(q,choice,confidence){const old=getStore().answers[q.id];getStore().answers[q.id]={choice,correct:choice===q.answer,confidence:confidence||'unsure',attempts:(old?.attempts||0)+1,firstCorrect:old?.needsReview?choice===q.answer:(old?.firstCorrect??choice===q.answer),time:Date.now()};track('answer',{questionId:q.id,choice,confidence:confidence||'unsure',attempts:getStore().answers[q.id].attempts,firstCorrect:getStore().answers[q.id].firstCorrect})}
 function finish(){const s=getStore().session;if(!s||s.finished)return;s.finished=true;s.ended=Date.now();for(const id of s.ids)if(s.responses[id]!==undefined&&s.mode==='exam')record(byId[id],s.responses[id],s.confidence[id]);track('session_finish',{bank:sessionBank(s),mode:s.mode,score:s.ids.filter(id=>s.responses[id]===byId[id].answer).length,total:s.ids.length});save();render()}
 function view(){const s=getStore().session;if(!s)return `<div class="empty"><h2>Start a practice set</h2><a href="#ib400" class="primary">Open IB400 →</a></div>`;orders(s);if(s.finished&&!s.review)return results();s.index=Math.max(0,Math.min(s.ids.length-1,s.index||0));const q=byId[s.ids[s.index]];if(!q)return '<div class="empty">Start a new set to load an available question.</div>';const bank=sessionBank(s),choice=s.responses[q.id],selected=choice??s.drafts[q.id],reveal=s.mode==='practice'&&choice!==undefined||s.finished,marks=s.strikes[q.id]||[];return `<a class="breadcrumb-back" href="#${bank}">← ${E(title(bank))}</a><div class="section-head" style="margin-top:0"><div><p class="eyebrow">${E(title(bank))} · ${s.finished?'REVIEW':s.mode.toUpperCase()}</p><h2>${s.finished?'Review the reasoning.':`One question. ${q.choices.length===6?'Six':'Five'} possibilities.`}</h2></div><span class="tag" id="session-timer">${s.end&&!s.finished?'Timer running':'Untimed'}</span></div><div class="quiz-layout"><article class="question-card"><div class="question-meta"><span class="question-id">QUESTION ${s.index+1} / ${s.ids.length} · ${E(label(q))}</span><span class="badge ${q.difficulty==='S&T'?'synthesis':E(q.difficulty)}">${E(q.difficulty)}</span><button class="bookmark ${getStore().bookmarks.includes(q.id)?'active':''}" id="bookmark" aria-label="${getStore().bookmarks.includes(q.id)?'Remove bookmark':'Bookmark question'}">${getStore().bookmarks.includes(q.id)?'★':'☆'}</button></div>${PB.brief(q)}<p class="eyebrow">${E(lesson(q.lesson)?.title)}</p><h2 lang="en">${E(q.prompt)}</h2><div class="translation-tools">${translationControl('question:'+q.id,[{text:q.prompt},...s.orders[q.id].map((i,j)=>({label:letters[j],text:q.choices[i].text}))],'Show Chinese translation · 中文')}</div><p class="choice-help">Choose an answer. Use <span class="strike-example">Cross out</span> to eliminate an option without selecting it.</p><div class="choices">${s.orders[q.id].map((i,position)=>{const c=q.choices[i],struck=marks.includes(i);return `<div class="choice-row ${struck?'is-struck':''}" data-row="${i}"><button class="choice ${selected===i?'selected ':''}${reveal?(i===q.answer?'correct':i===choice?'wrong':''):''}" data-choice="${i}" aria-pressed="${selected===i}" ${reveal?'disabled':''}><span class="letter">${letters[position]}</span><span><span class="choice-text">${E(c.text)}</span>${reveal?`<span class="choice-feedback">${E(c.feedback)}</span>`:''}</span></button><button class="strike-button ${struck?'active':''}" data-strike="${i}" aria-label="${struck?'Restore':'Cross out'} option ${letters[position]}" aria-pressed="${struck}" ${reveal?'disabled':''}>${struck?'Restore':'Cross out'}</button></div>`}).join('')}</div>${!s.finished?`<div class="confidence"><span>How certain are you?</span>${['guessed','unsure','confident'].map(c=>`<button data-confidence="${c}" class="${s.confidence[q.id]===c?'active':''}">${c[0].toUpperCase()+c.slice(1)}</button>`).join('')}</div>`:''}${reveal?`<div class="feedback ${choice===q.answer?'':'incorrect'}"><h3>${choice===undefined?'Unanswered':choice===q.answer?'Correct. Now check the mechanism.':'Revisit the mechanism.'} <span class="small">Answer ${letter(s,q.id,q.answer)}</span></h3><p lang="en">${E(q.explanation)}</p><div class="translation-tools">${translationControl('explanation:'+q.id,[{text:q.explanation},...s.orders[q.id].flatMap((i,j)=>[{label:letters[j],text:q.choices[i].text},{text:q.choices[i].feedback}]),...(q.rationale?[{label:'Why this is a stretch / 难点说明',text:q.rationale}]:[])],'Translate explanations · 中文')}</div>${q.rationale?`<p class="synthesis-reason"><strong>Why this is a stretch</strong><br>${E(q.rationale)}</p>`:''}<a class="inline-link" href="#decoded/${q.lesson}/${q.concept}">Understand this in Decoded ↗</a><p class="source-inline">${E(q.source)}</p></div>`:s.mode==='exam'?'<p class="small">Your selection is saved. Answers appear after finishing.</p>':''}<div class="question-actions"><button class="secondary" id="prev-question" ${s.index===0?'disabled':''}>← Previous</button><div class="group">${s.mode==='practice'&&!reveal?`<button class="primary" id="check-answer" ${selected===undefined?'disabled':''}>Check answer</button>`:''}<button class="${reveal||s.mode==='exam'?'primary':'secondary'}" id="next-question">${s.index===s.ids.length-1?'Finish & review':'Next →'}</button></div></div><div class="redo-row"><button class="quiet" id="redo-question">↻ ${s.finished?'Redo in a new practice set':reveal?'Redo this question':'Clear this attempt'}</button><span class="small">${getStore().answers[q.id]?.attempts||0} previous marked attempt${getStore().answers[q.id]?.attempts===1?'':'s'} · history retained</span></div></article><aside class="question-aside"><div class="session-box"><h3>${Object.keys(s.responses).length} of ${s.ids.length} answered</h3><p>Green means correct. Peach means revisit. Exam answers stay hidden until you finish.</p><div class="question-map">${s.ids.map((id,i)=>{const r=s.responses[id],show=s.finished||s.mode==='practice';return `<button data-index="${i}" class="${i===s.index?'active ':''}${r!==undefined?(show?(r===byId[id].answer?'right':'wrong'):'pending'):''}" aria-label="Go to question ${i+1}">${i+1}</button>`}).join('')}</div><button class="quiet" id="finish-session">${s.finished?'Back to results':'Finish this set'}</button></div><p class="small" style="margin-top:15px">Progress and crossed-out options are saved on this device and sync with your account. Export progress keeps a backup.</p></aside></div>`}
 function focusRender(selector){render(false);$(selector)?.focus({preventScroll:true})}
 function bindSession(){const s=getStore().session;if(!s)return;if(s.finished&&!s.review){bindResults();return}orders(s);const q=byId[s.ids[s.index]];if(!q)return;PB.bindBrief(q,save,render);bindTranslations();document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.choice);track('option_select',{questionId:q.id,choice:i});s.drafts[q.id]=i;s.strikes[q.id]=(s.strikes[q.id]||[]).filter(v=>v!==i);if(s.mode==='exam')s.responses[q.id]=i;save();focusRender(`[data-choice="${i}"]`)});document.querySelectorAll('[data-strike]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.strike),a=s.strikes[q.id]||[],adding=!a.includes(i);track('option_crossout',{questionId:q.id,choice:i,struck:adding});s.strikes[q.id]=adding?[...a,i]:a.filter(v=>v!==i);if(adding&&s.drafts[q.id]===i)delete s.drafts[q.id];if(adding&&s.responses[q.id]===i)delete s.responses[q.id];save();focusRender(`[data-strike="${i}"]`)});document.querySelectorAll('[data-confidence]').forEach(b=>b.onclick=()=>{s.confidence[q.id]=b.dataset.confidence;track('confidence',{questionId:q.id,confidence:b.dataset.confidence});if(s.mode==='practice'&&s.responses[q.id]!==undefined&&getStore().answers[q.id])getStore().answers[q.id].confidence=b.dataset.confidence;save();focusRender(`[data-confidence="${b.dataset.confidence}"]`)});$('#check-answer')?.addEventListener('click',()=>{const i=s.drafts[q.id];if(!validChoice(q.id,i))return;s.responses[q.id]=i;record(q,i,s.confidence[q.id]);save();render(false)});$('#bookmark').onclick=()=>{const b=getStore().bookmarks,n=b.indexOf(q.id);if(n<0)b.push(q.id);else b.splice(n,1);track('bookmark',{questionId:q.id,active:n<0});save();render(false)};$('#redo-question').onclick=()=>{track('redo_question',{questionId:q.id});if(s.finished){start([q.id],bankOf(q));return}delete s.responses[q.id];delete s.drafts[q.id];delete s.strikes[q.id];delete s.confidence[q.id];delete s.orders[q.id];save();render(false);toast('Fresh attempt. Your earlier result and attempt count are retained.')};$('#prev-question').onclick=()=>{s.index--;save();render(false)};$('#next-question').onclick=()=>{if(s.index<s.ids.length-1){s.index++;save();render(false)}else if(s.finished){s.review=false;save();render()}else finish()};$('#finish-session').onclick=()=>{if(s.finished){s.review=false;save();render()}else finish()};document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>{s.index=Number(b.dataset.index);save();render(false)});if(s.end&&!s.finished){const tick=()=>{const remaining=Math.max(0,Math.ceil((s.end-Date.now())/1000));if($('#session-timer'))$('#session-timer').textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')} remaining`;if(!remaining){clearInterval(timer);finish();toast('Time is up. Your saved answers have been marked.')}};tick();if(!s.finished)timer=setInterval(tick,1000)}}
 function results(){const s=getStore().session,bank=sessionBank(s),n=s.ids.filter(id=>s.responses[id]===byId[id].answer).length;orders(s);return `<p class="eyebrow">${E(title(bank))} · SESSION RESULTS</p><h1>Turn the mistakes into understanding.</h1><div class="result-score">${n} <span class="small">/ ${s.ids.length} correct</span></div><p class="intro">${Object.keys(s.responses).length} answered · ${s.ids.length-Object.keys(s.responses).length} unanswered · ${Math.round(n/s.ids.length*100)}% across the full set.</p><div class="actions"><button class="primary" id="review-all">Review every answer →</button><button class="secondary" id="retry-wrong">Redo incorrect & unanswered</button><button class="secondary" id="retry-all">Redo the full set</button><a class="secondary" href="#${bank}">Choose another set</a></div><div class="section-head"><h2>Your answer trail</h2><p>Every option has an explanation.</p></div><div class="review-list">${s.ids.map((id,i)=>{const q=byId[id],r=s.responses[id];return `<button class="review-item" data-review="${i}"><strong>${r===q.answer?'✓':r===undefined?'○':'×'} ${E(label(q))}</strong><span>${E(q.prompt)}<br><span class="small">${r===undefined?'Unanswered':`Your answer ${letter(s,id,r)}`} · Correct ${letter(s,id,q.answer)} · ${E(q.difficulty)}</span></span></button>`}).join('')}</div>`}
 function bindResults(){const s=getStore().session;$('#review-all').onclick=()=>{s.review=true;s.index=0;save();render()};document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{s.review=true;s.index=Number(b.dataset.review);save();render()});$('#retry-all').onclick=()=>start([...s.ids],sessionBank(s));$('#retry-wrong').onclick=()=>{const ids=s.ids.filter(id=>s.responses[id]!==byId[id].answer);if(!ids.length)return toast('Every question in this set is correct');start(ids,sessionBank(s))}}
 function cleanSession(s){if(!s||!Array.isArray(s.ids)||!s.ids.length||s.ids.some(id=>!Number.isInteger(id)||!byId[id])||!['practice','exam'].includes(s.mode))return null;const ids=[...new Set(s.ids)],bank=bankOf(byId[ids[0]]);if(ids.some(id=>bankOf(byId[id])!==bank))return null;const clean={bank,ids,mode:s.mode,index:Math.max(0,Math.min(ids.length-1,Math.floor(Number(s.index)||0))),responses:{},drafts:{},strikes:{},confidence:{},orders:{},finished:!!s.finished,review:!!s.review,started:Number(s.started)||Date.now(),end:Number(s.end)>0?Number(s.end):null};for(const id of ids){for(const key of ['responses','drafts'])if(validChoice(id,s[key]?.[id]))clean[key][id]=s[key][id];if(Array.isArray(s.strikes?.[id]))clean.strikes[id]=[...new Set(s.strikes[id].filter(v=>validChoice(id,v)))];if(['guessed','unsure','confident'].includes(s.confidence?.[id]))clean.confidence[id]=s.confidence[id];const a=s.orders?.[id];if(Array.isArray(a)&&a.length===byId[id].choices.length&&new Set(a).size===a.length&&a.every(v=>validChoice(id,v)))clean.orders[id]=a}return clean}
 return {lobby,bindLobby,view,bindSession,title,sessionBank,recapMap,cleanSession,start,bankOf,stop:()=>clearInterval(timer)};
}
